// IterList iterates over every item of every page of [KakaoSendersService.List].
// It starts at params.Page (default 1) and stops on an empty page, a page shorter than params.Rows, hasNext false or when the total is reached.
// A non-nil error is yielded once, as the last element.
func (s *KakaoSendersService) IterList(ctx context.Context, params ListKakaoSenderProfilesParams) iter.Seq2[KakaoSenderChannel, error] {
	return func(yield func(KakaoSenderChannel, error) bool) {
		var zero KakaoSenderChannel
		seen := 0
		position := 1
		if params.Page != nil {
			position = *params.Page
		}
		params.Page = &position
		for {
			resp, err := doListKakaoSenderProfiles(ctx, s.tr(), params)
			if err != nil {
				yield(zero, err)
				return
			}
			var items []KakaoSenderChannel
			if !(resp.Data == nil) {
				items = resp.Data.Channels
			}
			for _, item := range items {
				if !yield(item, nil) {
					return
				}
			}
			seen += len(items)
			if len(items) == 0 || (params.Rows != nil && len(items) < *params.Rows) {
				return
			}
			var hasNext *bool
			if !(resp.Data == nil) {
				hasNext = resp.Data.HasNext
			}
			if hasNext != nil && !*hasNext {
				return
			}
			if !(resp.Data == nil) && resp.Data.TotalCount != nil && int64(seen) >= int64(*resp.Data.TotalCount) {
				return
			}
			*params.Page++
		}
	}
}

